// Package impact 提供 Change Impact Analysis 功能
// 分析修改某個 Go 檔案後，會影響哪些套件、匯出 API、路由和測試
// 讓 AI 在修改程式碼前先確認影響範圍
//
// 純 AST 分析，不需要編譯專案，檔案改到一半也能跑。
//
// @ai:generated by=claude-opus-4-6 date=2026-02-27
package impact

import (
	"errors"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

// 風險等級
const (
	RiskLow    = "LOW"
	RiskMedium = "MEDIUM"
	RiskHigh   = "HIGH"
)

// ImpactReport 分析報告
type ImpactReport struct {
	Target      string   `json:"target"`             // 分析目標檔案
	Package     string   `json:"package"`            // 目標所屬套件（相對於專案根目錄）
	IsTestFile  bool     `json:"is_test_file"`       // 目標是 *_test.go
	Risk        string   `json:"risk"`               // LOW / MEDIUM / HIGH
	RiskReasons []string `json:"risk_reasons"`       // 風險等級的依據
	Warnings    []string `json:"warnings,omitempty"` // 分析不完整之處

	API        []SymbolUsage   `json:"api,omitempty"`        // 這個檔案的匯出 API 與外部使用情況
	Dependents []DependentFile `json:"dependents,omitempty"` // 直接依賴此套件的套件
	Transitive []TransitiveDep `json:"transitive,omitempty"` // 間接依賴此套件的套件

	RoutesKnown bool          `json:"routes_known"`     // 有 .hyp/context.yaml 可供比對
	Routes      []RouteImpact `json:"routes,omitempty"` // 受影響的路由（直接者在前）

	Tests            []TestImpact `json:"tests,omitempty"`             // 受影響的測試
	UntestedPackages []string     `json:"untested_packages,omitempty"` // 受影響但沒有測試的套件
	TestCommand      string       `json:"test_command,omitempty"`      // 跑受影響測試的指令
	NextSteps        []string     `json:"next_steps,omitempty"`        // 改完後還要做的事
}

// DependentFile 直接依賴此套件的套件
type DependentFile struct {
	Path     string   `json:"path"`                // 套件路徑（相對於專案根目錄）
	Package  string   `json:"package"`             // package 名稱
	TestOnly bool     `json:"test_only,omitempty"` // 只有 *_test.go import：不會往上傳遞
	Uses     []string `json:"uses,omitempty"`      // 用到這個檔案的哪些匯出符號
}

// TransitiveDep 間接依賴此套件的套件
type TransitiveDep struct {
	Path string `json:"path"`
	Via  string `json:"via"` // 經由哪個套件依賴（離目標較近的一層）
}

// TestImpact 受影響的測試
type TestImpact struct {
	File      string `json:"file"`       // 測試檔案路徑
	TestCount int    `json:"test_count"` // 測試數量
}

// Analyze 分析指定檔案的變更影響
//
// 使用範例：
//
//	report, err := impact.Analyze("pkg/errors/catalog.go", ".")
//	fmt.Print(impact.FormatReport(report))
func Analyze(targetFile string, projectRoot string) (*ImpactReport, error) {
	absTarget, err := filepath.Abs(targetFile)
	if err != nil {
		return nil, fmt.Errorf("invalid target path: %w", err)
	}
	absRoot, err := filepath.Abs(projectRoot)
	if err != nil {
		return nil, fmt.Errorf("invalid project root: %w", err)
	}
	// 先前以字串前綴判斷，/proj2/x.go 會通過 /proj 的檢查
	relTarget, err := filepath.Rel(absRoot, absTarget)
	if err != nil || relTarget == ".." || strings.HasPrefix(relTarget, ".."+string(filepath.Separator)) {
		return nil, fmt.Errorf("target file must be within project root")
	}
	// 先前不檢查：不存在的檔案回報「沒有依賴者、LOW」，等於告訴 AI 可以放心改
	info, err := os.Stat(absTarget)
	if errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("file not found: %s", targetFile)
	}
	if err != nil {
		return nil, err
	}
	if info.IsDir() || !strings.HasSuffix(absTarget, ".go") {
		return nil, fmt.Errorf("target must be a .go file: %s", targetFile)
	}

	targetPkg := packageFromFile(relTarget)
	proj, err := scanProject(absRoot)
	if err != nil {
		return nil, fmt.Errorf("failed to scan project: %w", err)
	}

	report := &ImpactReport{
		Target:     filepath.ToSlash(targetFile),
		Package:    targetPkg,
		IsTestFile: strings.HasSuffix(absTarget, "_test.go"),
	}
	reach := proj.reach(targetPkg)

	var decls *fileDecls
	if !report.IsTestFile {
		if decls, err = parseFileDecls(absTarget); err != nil {
			report.Warnings = append(report.Warnings, "cannot parse target file, exported API and direct routes unavailable: "+err.Error())
		}
	}
	usage := proj.scanUsage(targetPkg, decls, report)

	if !report.IsTestFile {
		for _, dep := range reach.direct {
			report.Dependents = append(report.Dependents, proj.dependent(dep, false, usage))
		}
		for _, dep := range reach.testOnly {
			report.Dependents = append(report.Dependents, proj.dependent(dep, true, usage))
		}
		sort.Slice(report.Dependents, func(i, j int) bool { return report.Dependents[i].Path < report.Dependents[j].Path })
		for _, dep := range reach.transitive {
			report.Transitive = append(report.Transitive, TransitiveDep{Path: dep, Via: reach.via[dep]})
		}
		report.API = usage.symbols(decls)
		report.applyRoutes(proj, decls, reach)
	}
	report.applyTests(proj, reach)
	report.Risk, report.RiskReasons = assessRisk(report)
	report.applyNextSteps(decls)
	return report, nil
}

// reachability 為依賴目標套件的範圍
type reachability struct {
	direct     []string          // 正式程式碼直接 import
	testOnly   []string          // 只有測試 import 目標
	transitive []string          // 經由其他套件依賴
	testUsers  []string          // 只有測試 import 上述 direct / transitive 的套件
	via        map[string]string // 間接依賴者 → 離目標較近的一層
}

// reach 沿正式程式碼的 import 反向走訪；測試的 import 不往上傳遞（套件的測試不屬於它對外的依賴）。
// 先前只看直接依賴：改 pkg/errors 時完全看不到經由 pkg/manifest 受影響的 pkg/server
func (p *project) reach(target string) reachability {
	r := reachability{via: map[string]string{}}
	all := sortedPackages(p.packages)
	seen := map[string]bool{target: true}
	queue := []string{target}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		for _, pkg := range all {
			if seen[pkg] || !p.packages[pkg].imports[current] {
				continue
			}
			seen[pkg] = true
			queue = append(queue, pkg)
			if current == target {
				r.direct = append(r.direct, pkg)
			} else {
				r.transitive = append(r.transitive, pkg)
				r.via[pkg] = current
			}
		}
	}
	for _, pkg := range all {
		if seen[pkg] {
			continue
		}
		if p.packages[pkg].testImports[target] {
			r.testOnly = append(r.testOnly, pkg)
			continue
		}
		for dep := range p.packages[pkg].testImports {
			if seen[dep] {
				r.testUsers = append(r.testUsers, pkg)
				break
			}
		}
	}
	sort.Strings(r.transitive)
	return r
}

func sortedPackages(pkgs map[string]*pkgInfo) []string {
	keys := make([]string, 0, len(pkgs))
	for k := range pkgs {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func (p *project) dependent(pkg string, testOnly bool, usage *usageIndex) DependentFile {
	return DependentFile{
		Path:     pkg,
		Package:  p.packages[pkg].name,
		TestOnly: testOnly,
		Uses:     usage.usedBy(pkg),
	}
}

// applyTests 列出受影響的測試、沒有測試的套件與測試指令
func (r *ImpactReport) applyTests(p *project, reach reachability) {
	affected := []string{r.Package}
	if !r.IsTestFile {
		affected = append(affected, reach.direct...)
		affected = append(affected, reach.transitive...)
		affected = append(affected, reach.testOnly...)
		affected = append(affected, reach.testUsers...)
	}
	sort.Strings(affected)

	var runnable []string
	for _, pkg := range affected {
		info := p.packages[pkg]
		if info == nil {
			continue
		}
		if info.tests > 0 {
			r.Tests = append(r.Tests, TestImpact{File: path.Join(pkg, "*_test.go"), TestCount: info.tests})
			runnable = append(runnable, goTestPath(pkg))
		} else if len(info.files) > 0 {
			r.UntestedPackages = append(r.UntestedPackages, pkg)
		}
	}
	if len(runnable) > 0 {
		r.TestCommand = "go test " + strings.Join(runnable, " ")
	}
}

func goTestPath(pkg string) string {
	if pkg == "." {
		return "."
	}
	return "./" + pkg + "/"
}

// applyNextSteps 依分析結果列出改完後要做的事
func (r *ImpactReport) applyNextSteps(decls *fileDecls) {
	if r.TestCommand != "" {
		r.NextSteps = append(r.NextSteps, r.TestCommand)
	}
	if decls != nil && decls.hasBunModel {
		r.NextSteps = append(r.NextSteps, "hyp migrate diff   # this file defines a bun model")
	}
	if r.directRouteCount() > 0 {
		r.NextSteps = append(r.NextSteps, "hyp context && hyp lint   # routes are declared against this file")
	}
}

// totalTests 回傳受影響的測試總數
func (r *ImpactReport) totalTests() int {
	total := 0
	for _, t := range r.Tests {
		total += t.TestCount
	}
	return total
}

// outsideTests 回傳目標套件以外的測試數
func (r *ImpactReport) outsideTests() int {
	total := r.totalTests()
	for _, t := range r.Tests {
		if t.File == path.Join(r.Package, "*_test.go") {
			total -= t.TestCount
		}
	}
	return total
}

// assessRisk 依影響範圍評估風險，並回傳依據。
// 只算正式程式碼的依賴者：只有測試 import 的套件不會在正式環境被影響。
// 測試數量最多拉到 MEDIUM：它代表要跑多少，不代表風險多高，而且算入間接依賴後很容易超標
// （舊規則「測試 >= 50 即 HIGH」套用後，只有 1 個依賴者的 pkg/websocket/proto 也是 HIGH）
func assessRisk(r *ImpactReport) (string, []string) {
	if r.IsTestFile {
		return RiskLow, []string{"test file: only affects its own package's tests"}
	}
	direct := 0
	for _, dep := range r.Dependents {
		if !dep.TestOnly {
			direct++
		}
	}
	total := direct + len(r.Transitive)
	outside := r.outsideTests()
	directRoutes := r.directRouteCount()

	level := 0
	var reasons []string
	raise := func(to int, reason string) {
		if to > level {
			level = to
		}
		reasons = append(reasons, reason)
	}

	switch {
	case total == 0:
		reasons = append(reasons, "no other package depends on this one")
	case direct >= 5:
		raise(2, fmt.Sprintf("%d packages import it directly, %d depend on it in total", direct, total))
	case total >= 6:
		raise(2, fmt.Sprintf("%d packages depend on it (%d directly)", total, direct))
	case direct >= 2 || total >= 3:
		raise(1, fmt.Sprintf("%d packages depend on it (%d directly)", total, direct))
	default:
		reasons = append(reasons, fmt.Sprintf("%d package(s) depend on it", total))
	}
	if outside >= 20 {
		raise(1, fmt.Sprintf("%d tests in other packages are affected", outside))
	}
	if directRoutes > 0 {
		raise(1, fmt.Sprintf("%d route(s) declared directly against this file", directRoutes))
	}
	// 有人依賴卻沒有測試保護時，錯誤最容易直接進到正式環境。最多拉到 MEDIUM：
	// 否則只有 1 個依賴者的 pkg/websocket/proto（protoc 產物）也會變成 HIGH
	if total > 0 && !r.hasOwnTests() {
		if level == 0 {
			level = 1
		}
		reasons = append(reasons, "this package has no tests of its own")
	}
	return []string{RiskLow, RiskMedium, RiskHigh}[level], reasons
}

func (r *ImpactReport) hasOwnTests() bool {
	for _, t := range r.Tests {
		if t.File == path.Join(r.Package, "*_test.go") {
			return true
		}
	}
	return false
}

// packageFromFile 從檔案路徑推導套件路徑（相對於 project root）
func packageFromFile(file string) string {
	return filepath.ToSlash(filepath.Dir(file))
}
